--- a/mm/ptdump.c
+++ b/mm/ptdump.c
@@ -190,6 +190,17 @@ void ptdump_walk_pgd(struct ptdump_state *st, struct mm_struct *mm, pgd_t *pgd)
        st->note_page_flush(st);
 }

+int ptdump_pt_level_first(struct mm_struct *mm)
+{
+       if (mm_pmd_folded(mm))
